import {ContractError} from './cloud-contract.mjs';
import {hasSensitive} from './admin-permissions.mjs';
import {cardMoney} from './phone-card-finance-contract.mjs';
const decimal=n=>n===null||n===undefined?'':(n<0?'-':'')+Math.floor(Math.abs(n)/100)+'.'+String(Math.abs(n)%100).padStart(2,'0');
export function createPhoneCardFinanceEditors({api,h,mount,input,area,select}){
 async function recharge(id,root){
  const [s,options,ledger,r]=await Promise.all([api.cardFinanceState(id),api.phoneCardOptions(),api.finance(),root?api.cardRecharge(id,root):null]);if(r?.status==='voided')throw new ContractError('已作废记录保留历史，不能再次修改。');
  const key=crypto.randomUUID(),kind=root?'correct':'recharge',choices=options.members.map(m=>[m.id,m.name+(m.active?'':'（已停用）')]);if(r?.expenseId&&!ledger.records.some(e=>e.id===r.expenseId))throw new ContractError('原支出未完整读取，请重试。');
  const handler=r?'preserve':'operator',fields=`<p>${h(s.card.cardCode)} · ${h(s.card.phoneNumber)}</p><p class="planning-rule">登记已发生的充值，不执行运营商充值或新增账本支出。充值金额、经办人、实际付款人和费用归属分别记录；余额需另行查询手记。</p>${r?.sourceChanged?'<p class="save-error">原支出已变更，请核对当前来源及本次修正原因。</p>':''}${r&&r.cardSnapshot.phoneNumber!==s.card.phoneNumber?`<p class="muted">此充值最初登记时号码：${h(r.cardSnapshot.phoneNumber)}，修正保留原卡片来源。</p>`:''}`+input('rechargeDate','实际充值日期',r?.rechargeDate||s.today,`required type="date" max="${s.today}"`)+input('amount','充值金额（元）',decimal(r?.amountCents),'required inputmode="decimal" maxlength="11"')+(r?'':'<div class="action-row">快捷金额：'+[30,50,100,200].map(n=>`<button class="secondary" type="button" data-recharge-amount="${n}">${n} 元</button>`).join('')+'</div>')+input('rechargeType','类型',r?.rechargeType||'话费充值','required maxlength="80" list="card-recharge-types"')+'<datalist id="card-recharge-types"><option value="话费充值"><option value="套餐续费"><option value="流量包"><option value="其他"></datalist>'+select('handler','实际经办人',handler,[...(r?[['preserve','保留原经办人：'+r.handlerName]]:[]),['operator','当前操作人：'+s.operatorName],...choices])+select('payer','实际付款方',r?.payerKind==='member'?r.payerMemberId:'company',[['company','公司付款'],...choices])+select('storeId','费用归属',r?r.storeId||'':s.card.storeId||'',[['','工作室／公共业务'],...options.stores.map(v=>[v.id,v.name+(v.active?'':'（已停用）')])])+input('businessPurpose','业务用途',r?.businessPurpose||'运营通信','required maxlength="200"')+select('expenseId','引用已有支出',r?.expenseId||'',[['','暂不关联'],...ledger.records.map(e=>[e.id,`${e.expenseDate} · ${e.description} · ${cardMoney(e.amountCents)}`])])+'<p class="muted">支出引用仅作来源核对，不自动分摊或重复计费；充值金额可能与实际支付金额不同。</p>'+area('note','充值备注',r?.note||'')+(r?'':select('reminderMode','充值后的日期提醒','keep',[['keep','保留当前提醒'],['set','设置下次充值日期'],['clear','清除此日期提醒']])+input('nextRechargeOn','下次充值日期',s.reminder?.nextRechargeOn||'','type="date"'))+area('reason',r?'本次修正原因（必填）':'本次登记说明',r?'':'实际充值登记');
  mount(r?'修正充值记录':'登记手机卡充值',fields,f=>{
   const handled=f.get('handler'),paid=f.get('payer'),source=ledger.records.find(e=>e.id===f.get('expenseId'));if(f.get('expenseId')&&!source)throw new ContractError('原支出未读取完整。');const value={requestKey:key,expectedCardVersion:s.card.version,rechargeDate:f.get('rechargeDate'),amount:f.get('amount').trim(),rechargeType:f.get('rechargeType'),handlerKind:handled==='operator'?'operator':handled==='preserve'?'preserve':'member',handlerMemberId:['operator','preserve'].includes(handled)?null:handled,payerKind:paid==='company'?'company':'member',payerMemberId:paid==='company'?null:paid,storeId:f.get('storeId')||null,businessPurpose:f.get('businessPurpose'),expenseId:source?.id||null,expenseVersion:source?.version||null,note:f.get('note'),reason:f.get('reason')};
   if(r)value.expectedVersion=r.version;else{const mode=f.get('reminderMode');Object.assign(value,{reminderMode:mode,expectedReminderVersion:mode==='keep'?null:s.reminder?.version||0,nextRechargeOn:mode==='set'?f.get('nextRechargeOn'):null});}return api.saveCardRecharge(id,value,root);
  },{kind:'card-operation',cardId:id,operation:kind},()=>api.cardOperationReceipt(kind,id,key,root),form=>{form.querySelectorAll('[data-recharge-amount]').forEach(button=>button.onclick=()=>{const el=form.elements.amount;if(el.disabled)return;el.value=button.dataset.rechargeAmount;el.dispatchEvent(new Event('input',{bubbles:true}));});});
 }
 async function voidRecharge(id,root){const [s,r]=await Promise.all([api.cardFinanceState(id),api.cardRecharge(id,root)]);if(r.status!=='recorded')throw new ContractError('此充值已经作废。');const key=crypto.randomUUID();mount('作废充值登记',`<p>${h(r.rechargeDate)} · ${h(cardMoney(r.amountCents))} · ${h(r.rechargeType)}</p><p>作废会保留原记录和说明，不办理退款、修改原支出或推算余额。日期提醒请另行核对。</p>`+area('reason','作废原因（必填）'),f=>api.voidCardRecharge(id,root,{requestKey:key,expectedCardVersion:s.card.version,expectedVersion:r.version,reason:f.get('reason')}),{kind:'card-operation',cardId:id,operation:'void'},()=>api.cardOperationReceipt('void',id,key,root));}
 async function balance(id){const s=await api.cardFinanceState(id),key=crypto.randomUUID(),when=new Date(Date.parse(s.serverNow)+8*3600000).toISOString().slice(0,23);mount('登记查询余额',`<p>${h(s.card.cardCode)} · ${h(s.card.phoneNumber)}</p><p class="planning-rule">填写实际查询到的运营商余额和查询时点。支持负数表示欠费；填0表示确认是零，留空表示当前待确认。充值、修正和作废都不会自动改变此余额。</p>`+input('amount','查询余额（元，未知留空）','','inputmode="decimal" maxlength="12"')+input('observedAt','实际查询时间（北京时间）',when,'required type="datetime-local" step="0.001"')+area('note','查询来源与说明（必填）'),f=>{const time=f.get('observedAt');return api.saveCardBalance(id,{requestKey:key,expectedCardVersion:s.card.version,expectedVersion:s.balance?.version||0,amount:f.get('amount').trim()||null,observedAt:time+(time.length===16?':00':'')+'+08:00',note:f.get('note')});},{kind:'card-operation',cardId:id,operation:'balance'},()=>api.cardOperationReceipt('balance',id,key));}
 async function reminder(id){const user=await api.session();if(!hasSensitive(user,'resources'))throw new ContractError('需要资源管理授权。');const s=await api.cardReminderState(id),key=crypto.randomUUID();mount('设置下次充值提醒',`<p>${h(s.card.cardCode)} · ${h(s.card.phoneNumber)}</p><p>日期提醒独立于充值和余额。留空清除此日期提醒；套餐到期及使用中卡片的缺失关联仍按原资料提示。</p>`+input('nextRechargeOn','下次充值日期',s.latest?.nextRechargeOn||'','type="date"')+area('note','设置或清除说明（必填）')+'<p class="muted">此说明供资源管理员查看，请勿填写金额或实名资料。</p>',f=>api.saveCardReminder(id,{requestKey:key,expectedCardVersion:s.card.version,expectedVersion:s.latest?.version||0,nextRechargeOn:f.get('nextRechargeOn')||null,note:f.get('note')}),{kind:'card-operation',cardId:id,operation:'reminder'},()=>api.cardOperationReceipt('reminder',id,key));}
 return {cardRecharge:recharge,cardVoid:voidRecharge,cardBalance:balance,cardReminder:reminder};
}
